// test/OrderConfirmationUseCase.test.ts
import { jest } from '@jest/globals';
import { PostgresOrderRepository } from '../infra/postgres/PostgresOrderRepository';
import { StripePaymentAdapter } from '../infra/payment/StripePaymentAdapter';
import { SendGridEmailAdapter } from '../infra/email/SendGridEmailAdapter';
import { OrderConfirmationUseCase } from '../domain/OrderConfirmationUseCase';

jest.mock('../infra/postgres/PostgresOrderRepository');
jest.mock('../infra/payment/StripePaymentAdapter');
jest.mock('../infra/email/SendGridEmailAdapter');

describe('OrderConfirmationUseCase', () => {
  it('calls stripe charge and saves order on success', async () => {
    const mockRepo = new PostgresOrderRepository() as jest.Mocked<PostgresOrderRepository>;
    const mockStripe = new StripePaymentAdapter() as jest.Mocked<StripePaymentAdapter>;
    const mockEmail = new SendGridEmailAdapter() as jest.Mocked<SendGridEmailAdapter>;

    mockRepo.findById.mockResolvedValue({ id: 'o-1', status: 'pending', totalAmount: { inCents: () => 5000, currency: 'USD' }, customerId: 'c-1', customerEmail: 'a@b.com' });
    mockStripe.chargeCustomer.mockResolvedValue({ id: 'ch_123', status: 'succeeded' });
    mockEmail.sendConfirmation.mockResolvedValue(undefined);

    const useCase = new OrderConfirmationUseCase(mockRepo, mockStripe, mockEmail);
    const result = await useCase.confirmOrder('o-1', 'approver-1');

    expect(mockRepo.findById).toHaveBeenCalledWith('o-1');
    expect(mockStripe.chargeCustomer).toHaveBeenCalledWith('c-1', { inCents: expect.any(Function), currency: 'USD' });
    expect(mockRepo.save).toHaveBeenCalled();
    expect(result.success).toBe(true);
  });
});
